def integrate_function(func, a, b, epsabs, epsrel, workspace_size):
    workspace = CQuadWorkspace(workspace_size)
    gsl_integration_cquad = gsl.integrate_cquad
    result = gsl_integration_cquad(GSLFunction(func), a, b, epsabs, epsrel, byref(workspace))
    return result.integral, workspace.abserr, workspace.neval

import ctypes
from gsl import integrate_function
class GSLFunction:
    def __init__(self, func):
        self.func = func
    def __call__(self, x):
        return self.func(x)

def integrate(func, a, b, epsabs=1e-6, epsrel=1e-6, workspace_size=1024):
    gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    workspace = gsl.gsl_integration_cquad_alloc(workspace_size)
    try:
        result = integrate_function(GSLFunction(func), a, b, epsabs, epsrel, workspace)
    except ctypes.ArgumentError as e:
        print(f'Error during integration: {e}')
        return None, None, None
    finally:
        gsl.gsl_integration_cquad_free(workspace)
    return result[0], result[1], result[2]

