        raise NotImplementedError()

def integrate_with_singularity(func: Callable[[float], float], a: float, b: float, c: float) -> Tuple[float, float, int]:
    params = ctypes.c_void_p()
    gsl.qc25c_alloc(params)
    gsl.qc25c_set(params, func=func, a=a, b=b, c=c)
    result = gsl.qc25c_integrate(params)
    return result[0], result[1], result[2]

