class gsl_permutation(ctypes.Structure):
    _fields_ = [('n', ctypes.c_int), ('p', ctypes.POINTER(ctypes.c_int))]

class gsl_vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double)), ('size', ctypes.c_int)]

def permute_vector(permutation, vector):
    if len(permutation) != len(vector):
        raise ValueError("Permutation and vector lengths must match.")
    perm = gsl_permutation()
    perm.p = (ctypes.cast(ctypes.c_int * len(permutation), ctypes.POINTER(ctypes.c_int)))
    for i in range(len(permutation)):
        perm.p[i] = permutation[i]
    vec = gsl_vector()
    vec.data = (ctypes.cast(ctypes.c_double * len(vector), ctypes.POINTER(ctypes.c_double)))
    for i in range(len(vector)):
        vec.data[i] = vector[i]
    gsl.permute_vector(perm, vec)
    return [vec.data[i] for i in range(len(vector))]

