        gsl.gsl_permutation_init(self._perm, len(data))
        for i in range(len(data)):
            gsl.gsl_permutation_set(self._perm, i, data[i])

    def write(self, filename: str):
        with open(filename, 'wb') as f:
            ret = gsl.gsl_permutation_fwrite(self._perm, file=f)
            if ret != 0:
                raise RuntimeError(f"Error writing permutation to {filename}")
    def read(self, filename: str):
        with open(filename, 'rb') as f:
            ret = gsl.gsl_permutation_fread(self._perm, file=f)
            if ret != 0:
                raise RuntimeError(f"Error reading permutation from {filename}")

def write_and_read_permutation(perm_list: List[int]):
