  size = ctypes.c_int(len(array))
  ptr = (ctypes.POINTER(ctypes.c_double) * size)() 
  for i in range(size):
    ptr[i] = array[i]
  return gsl.gsl_vector_view(ptr, size)

def create_gsl_matrix(matrix):
  rows = ctypes.c_int(len(matrix))
  cols = ctypes.c_int(len(matrix[0]))
  ptr = (ctypes.POINTER(ctypes.c_double) * rows * cols)() 
  for i in range(rows):
    for j in range(cols):
      ptr[i * cols + j] = matrix[i][j]
  return gsl.gsl_matrix_view(ptr, rows, cols)

