import ctypes
from typing import List

class GSLMatrix:
    def __init__(self, data: List[List[float]]):
        self.data = data

    def __str__(self):
        return str(self.data)

def matrix_to_gsl(matrix: List[List[float]]) -> ctypes.POINTER(ctypes.c_double):
    rows = len(matrix)
    cols = len(matrix[0])
    ptr = (ctypes.c_double * rows * cols)() 
    for i in range(rows):
        for j in range(cols):
            ptr[i * cols + j] = matrix[i][j]
    return ptr

def gsl_matrix_to_numpy(gsl_matrix: ctypes.POINTER(ctypes.c_double)) -> List[List[float]]:
    rows = gsl_matrix.contents.size // len(gsl_matrix.contents)
    cols = len(gsl_matrix.contents) // rows
    data = [ [gsl_matrix.contents[i * cols + j] for j in range(cols)] for i in range(rows) ]
    return data

def compute_matrix_exponential(matrix: List[List[float]], mode: int) -> List[List[float]]:
    try:
        libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        matrix_ptr = matrix_to_gsl(matrix)
        rows = len(matrix)
        cols = len(matrix[0])
        if rows != cols:
            raise ValueError('Input matrix must be square.')
        exp_matrix_ptr = gsl.gsl_linalg_exponential_ss(rows, matrix_ptr, mode)
        exp_matrix = gsl_matrix_to_numpy(exp_matrix_ptr)
        return exp_matrix
    except Exception as e:
        print(f'Error: {e}')
        return None

