class gsl_matrix(object):
    def __init__(self, rows, cols):
        self._ptr = gsl.gsl_matrix_alloc(rows, cols)

    def get(self, i, j):
        return gsl.gsl_matrix_get(self._ptr, i, j)

    def set(self, i, j, value):
        gsl.gsl_matrix_set(self._ptr, i, j, value)

class gsl_permutation(object):
    def __init__(self, size):
        self._ptr = gsl.gsl_permutation_alloc(size)

    def get(self, i):
        return gsl.gsl_permutation_get(self._ptr, i)

def cholesky_decomposition(input_matrix):
    rows = len(input_matrix)
    cols = len(input_matrix[0])
    if rows != cols:
        raise ValueError('Input matrix must be square')

    matrix = gsl_matrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.set(i, j, input_matrix[i][j])

    perm = gsl_permutation(rows)
    gsl.gsl_linalg_pcholesky_decomp(matrix._ptr, perm._ptr)

    modified_matrix = [[matrix.get(i, j) for j in range(cols)] for i in range(rows)]
    permutation = [perm.get(i) for i in range(rows)]
    return modified_matrix, permutation

def main():
    input_matrix = [[4, 2], [2, 3]]
    modified_matrix, permutation = cholesky_decomposition(input_matrix)
    print('Modified Matrix:', modified_matrix)
    print('Permutation Vector:', permutation)

if __name__ == '__main__':
    main()

