import ctypes
from typing import List

gslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

class GSLMatrix:
    def __init__(self, rows: int, cols: int):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()

    def transpose(self):
        gslcblas.gsl_matrix_transpose(self.data, self.rows, self.cols)

    def get_data(self) -> List[List[float]]:
        return [[self.data[i * self.cols + j] for j in range(self.cols)] for i in range(self.rows)]

def transpose_matrix(matrix: List[List[float]]) -> List[List[float]]:
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix.data[i * cols + j] = matrix[i][j]
    return gsl_matrix.get_data()

def verify_transpose(original: List[List[float]], transposed: List[List[float]]):
    for i in range(len(original)):
        for j in range(len(original[0])):
            assert original[j][i] == transposed[i][j]

if __name__ == '__main__':
    matrix = [[1, 2], [3, 4]]
    transposed_matrix = transpose_matrix(matrix)
    verify_transpose(matrix, transposed_matrix)
    print(transposed_matrix)

