class GSLMatrix:
    def __init__(self, data: List[List[float]]):
        self._data = data
        self._rows = len(data)
        self._cols = len(data[0])

    def to_gsl(self) -> gsl.gsl_matrix:
        return gsl.gsl_matrix_alloc(self._rows, self._cols),

class GSLVector:
    def __init__(self, data: List[float]):
        self._data = data
        self._size = len(data)

    def to_gsl(self) -> gsl.gsl_vector:
        return gsl.gsl_vector_alloc(self._size),

def matrix_to_gsl(matrix: GSLMatrix) -> gsl.gsl_matrix:
    return gsl.gsl_matrix_calloc(matrix._rows, matrix._cols)

def vector_to_gsl(vector: GSLVector) -> gsl.gsl_vector:
    return gsl.gsl_vector_alloc(vector._size)

def gsl_matrix_to_list(matrix: gsl.gsl_matrix) -> List[List[float]]:
    rows = matrix.size1
    cols = matrix.size2
    data = [[matrix[i, j] for j in range(cols)] for i in range(rows)]
    return data

def gsl_vector_to_list(vector: gsl.gsl_vector) -> List[float]:
    return [vector[i] for i in range(vector.size)]

def ql_decomposition_and_unpack(A: GSLMatrix, tau: List[float]) -> tuple[GSLMatrix, GSLMatrix]:
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(GSLVector(tau))
    Q, L = gsl.gsl_linalg_QL_decomp(A_gsl, tau_gsl)
    return GSLMatrix(gsl_matrix_to_list(Q)), GSLMatrix(gsl_matrix_to_list(L))

def main():
    A = [[1, 2], [3, 4]]
    tau = [0.5, 1]
    Q, L = ql_decomposition_and_unpack(GSLMatrix(A), tau)
    return Q._data, L._data
